// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.initialize(
            address(0),
            address(0x123),
            1000e18,
            1000e18,
            0,
            1000,
            bytes32(0),
            false,
            false
        );
        uint256 storedFeeRate = c.feeRate();
        assertTrue(storedFeeRate != 0, "feeRate should be non-zero after initialization");
    }
}
